local P = LoreForeverPacks.Begin("LoreForever_Voice_Default_MoreQuests3")
P.transportVersion = 1
P.transport = {}
P.transport["quest:1052"] = {
  hash = "4d7c0d",
  fullHash = "4d7c0d",
  text = "Down the Scarlet Path. Brother Anton says your deeds against the undead in Desolace are only a start, because the plague's real danger is in Lordaeron. He gives you a letter of commendation bearing his seal for Raleigh the Devout in Southshore. Anton speaks proudly of the Scarlet Crusade's bastions of cleansing in Lordaeron. The Crusade claims strongholds all the way between Hearthglen and Tirisfal Glades. Anton says your work against the undead in Desolace has proven you, yet the plague's real danger is in Lordaeron. Anton sends you to Southshore, a town in the Eastern Kingdoms, to look for a crusader called Raleigh the Devout. The letter carries Anton's seal, and Anton says it will win you an escort from Raleigh to a place of honor within the Scarlet Monastery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1052-8c7523ce3231e306e2c1/1-0000.mp3", duration = 41.1428571, start = 0},
  },
}
P.transport["quest:1118"] = {
  hash = "4b7561",
  fullHash = "4b7561",
  text = "Back to Booty Bay. Kravel Koalbeard trusts you to get a job done and to keep quiet about it. He has a new scheme, risky but with the promise of a bundle for you both. You carry his letter to Crank Fizzlebub in Booty Bay. This follows Rumors for Kravel. Kravel Koalbeard, the dwarf at the Mirage Raceway, calls you someone he can trust, both to finish a job and to hold your tongue about it. His new scheme carries risk, yet if it pays off the two of you stand to make a bundle. He apologizes for sending you back to Booty Bay, where his last job took you, and asks you to find Crank Fizzlebub there and hand over a letter. If Crank needs help, Kravel wants you to do your best, and says it will be worth the effort.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1118-99b8e0bf632aeb5793c8/1-0000.mp3", duration = 42.0832653, start = 0},
  },
}
P.transport["quest:1119"] = {
  hash = "752ad1",
  fullHash = "752ad1",
  text = "Zanzil's Mixture and a Fool's Stout. Crank Fizzlebub has found that Zanzil's Mixture blended into stout makes a strong drink, called Fool's Stout. He thinks it will be just what Kravel needs. You carry it to Kravel Koalbeard at the Mirage Raceway on the Shimmering Flats, and quickly, because it will not stay fresh. Crank Fizzlebub has found that Zanzil's Mixture, blended into stout, gives a strong drink, the Fool's Stout. Crank thinks it will be just what Kravel needs, and wants to hear how it works. You carry it back to Kravel Koalbeard at the Mirage Raceway on the Shimmering Flats. Crank warns you against holding on to the stout for long. The mixture has an odd effect on the stout's yeast, pushing it into high gear, so the drink will not keep fresh forever.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1119-1d617f03fef198b4c140/1-0000.mp3", duration = 40.6465306, start = 0},
  },
}
P.transport["quest:1120"] = {
  hash = "585815",
  fullHash = "585815",
  text = "Get the Gnomes Drunk. Kravel Koalbeard wants the Fool's Stout tested on a pit crew at the Mirage Raceway. If you choose the gnomes, you take the stout to the Gnome Pit Boss. The stout will go bad eventually, so Kravel says not to wait too long. Kravel Koalbeard needs the Fool's Stout tried out on one of the pit crews. You may try it on the gnomes: he hands you the stout and sends you with it to the Gnome Pit Boss, who is nearby at the Mirage Raceway. Choosing the gnomes tips the races toward the goblins. Kravel warns you not to dawdle, because the stout will go bad eventually.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1120-5f6e6d4810fa2c958cec/1-0000.mp3", duration = 30.3281633, start = 0},
  },
}
P.transport["quest:1121"] = {
  hash = "133cc4",
  fullHash = "133cc4",
  text = "Get the Goblins Drunk. Kravel Koalbeard wants the Fool's Stout tested on a pit crew at the Mirage Raceway. If you choose the goblins, you take the stout to the Goblin Pit Boss. The stout will go bad eventually, so Kravel says not to wait too long. Kravel Koalbeard needs the Fool's Stout tried out on one of the pit crews. You may try it on the goblins: he hands you the stout and sends you with it to the Goblin Pit Boss, who is nearby at the Mirage Raceway. Choosing the goblins tips the races toward the gnomes. Kravel warns you not to dawdle, because the stout will go bad eventually.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1121-7230aa44e9f744428e63/1-0000.mp3", duration = 33.5412245, start = 0},
  },
}
P.transport["quest:1122"] = {
  hash = "4ef7c2",
  fullHash = "4ef7c2",
  text = "Report Back to Fizzlebub. Kravel Koalbeard says the Fool's Stout worked great. He has put money on the next race, hoping the crew you made drunk wrecked their own car. You carry a note about the successful test to Crank Fizzlebub in Booty Bay. This follows the pit crew you chose to make drunk. Kravel Koalbeard says the Fool's Stout worked great. He has put money on the next race, hoping the pit crew you made drunk wrecked their own car. One more job remains: take a note about the successful test to Crank Fizzlebub in Booty Bay, who will want to hear of it. Kravel also hopes more of the stout can be had for future races.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1122-2f4399637b8d2ec647aa/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["quest:1127"] = {
  hash = "f740cf",
  fullHash = "f740cf",
  text = "Fool's Stout. Crank Fizzlebub in Booty Bay brews batches of Fool's Stout for travelers looking to return to the Shimmering Flats raceway. To concoct another serving, he requires twelve flasks of Zanzil's mixture. For travelers whose initial supply of Fool's Stout has expired before reaching the gnomes at the raceway, Crank Fizzlebub offers to brew a replacement. The goblin Crank Fizzlebub in Booty Bay requires twelve flasks of Zanzil's mixture to prepare the potent beverage once more, compensating anyone willing to fetch the ingredients while offering a little extra to keep the transaction discreet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1127-d49e91a4e5ec78511715/1-0000.mp3", duration = 33.1232653, start = 0},
  },
}
P.transport["quest:1188"] = {
  hash = "2804bd",
  fullHash = "2804bd",
  text = "Safety First. Razzeric has found that Shreev left the safety on the seaforium booster. It caps the power Razzeric gets out of the booster, and Razzeric had asked for it to be taken off. You are sent to Shreev in Gadgetzan, in Tanaris. Razzeric looks over the seaforium booster and finds the safety still on. It caps the power the booster can give, and Razzeric had told Shreev it should be off. Razzeric gives you the booster and sends you south of the Shimmering Flats into the Tanaris desert, to the Gadgetzan Gizmorium, to have Shreev remove the safety.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1188-2f466f69af57e98d5a67/1-0000.mp3", duration = 32.1044898, start = 0},
  },
}
P.transport["quest:1189"] = {
  hash = "e9cf2e",
  fullHash = "e9cf2e",
  text = "Safety First. Shreev has done what Razzeric wanted with the seaforium booster, and you carry the modified booster back to Razzeric on the Shimmering Flats. Shreev's warning with it: be careful when setting it off, because one slip and Razzeric ends up a scorch mark on the track. This follows the first Safety First. Shreev hands over the modified booster, done as Razzeric asked. Shreev's warning with it: Razzeric needs to be careful when he sets it off. A single slip and he will not be racing ahead; he will be a scorch mark on the track. Shreev adds that it would be a shame, wondering whether the nineteenth driver would have been any good. Back on the Shimmering Flats, Razzeric is grumbling about Pozzik, who loaded a bucket of sand onto the racer. How, Razzeric asks, is he meant to reach top speed with sand beneath the seat?",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1189-528fc3c65776f0d0b339/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["quest:1190"] = {
  hash = "e3f32b",
  fullHash = "e3f32b",
  text = "Keeping Pace. Pozzik is sure the Brassbolts brothers have found a new building material. Their cars run faster than before, yet their designs and the rest of the data from their runs are unchanged. Rizzle Brassbolts has stayed fixed on the plans for this discovery almost constantly, and Zamek can create a diversion so you can steal them. This follows News for Fizzle. Pozzik can find only one explanation for how fast the Brassbolts brothers' cars have become: a new building material. Their designs and everything gathered from their runs look the same as before. What is known is that Rizzle Brassbolts has stayed fixed on the plans for this discovery almost constantly. Zamek can create a diversion, and while it lasts you steal Rizzle's plans. They are wanted by Pozzik, on the Shimmering Flats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1190-5538a219635a1445d0c2/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["quest:1191"] = {
  hash = "04afec",
  fullHash = "04afec",
  text = "Zamek's Distraction. In Thousand Needles, Zamek's Distraction can draw Rizzle away while you work through Keeping Pace. You cannot finish Keeping Pace without it. While you work through Keeping Pace, Zamek draws Rizzle from his hut. The Indurium plans remain behind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1191-cc71ddec0d0ba3bfea1c/1-0000.mp3", duration = 15.4383673, start = 0},
  },
}
P.transport["quest:1192"] = {
  hash = "9c9f50",
  fullHash = "9c9f50",
  text = "Indurium Ore. Pozzik plans to work indurium into several parts of the racers, which calls for a great deal of raw ore. The ore is to be had at the Uldaman dig in the Badlands, across the sea in Khaz Modan. The gnomes are already getting hold of their own, and Pozzik wants to keep up with them. Pozzik asks for four pieces of raw indurium ore. It can be had at the Uldaman dig in the Badlands, across the sea in Khaz Modan. The gnomes are already getting hold of their own, so Pozzik wants a supply too. This follows Rizzle's Schematics.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1192-0f7a83c585aa42ac6184/1-0000.mp3", duration = 32.7314286, start = 0},
  },
}
P.transport["quest:1194"] = {
  hash = "63cb39",
  fullHash = "63cb39",
  text = "Rizzle's Schematics. Rizzle's unguarded plans describe the refining of indurium ore. The scrawls point to the dwarves' dig at Uldaman, in the Badlands, as where the ore comes from, and many of the other notes are about heat resistance. A lump of raw ore sits on the plans as a paperweight, and you carry that sample to Pozzik on the Shimmering Flats. This follows Keeping Pace. Rizzle's schematics describe the refining of indurium ore. Rizzle's scrawls point to the dwarves' dig at Uldaman, in the Badlands, as where the ore comes from. Many of the other notes are about how well it resists heat. A lump of raw indurium ore holds the plans down as a paperweight, and that sample is what you take to Pozzik.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1194-7dcd950081e4c3120414/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["quest:1380"] = {
  hash = "af3474",
  fullHash = "af3474",
  text = "Khan Hratha. Uthek the Wise recalls how you helped the Gelkis against the Magram, and now asks you to strike at the Maraudine by slaying their clan's leader, Khan Hratha. Hratha holds a piece of a key, and Uthek wants it brought to him. Uthek the Wise says the Gelkis now need help against the Maraudine. The Maraudine War Horn stands on a tall bluff in the Valley of Spears, and sounding it is how Khan Hratha is called out. Yet the horn is useless without a warhorn mouthpiece, which is rare and carried only by trusted Maraudine centaur. When the horn sounds, more centaur arrive, and Hratha comes last. Khan Hratha holds a piece of a key, and Uthek wants it brought to Gelkis Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1380-9c19b9adb6de18ab3ff0/1-0000.mp3", duration = 39.9412245, start = 0},
  },
}
P.transport["quest:1381"] = {
  hash = "b2fe0d",
  fullHash = "b2fe0d",
  text = "Khan Hratha. Warug announces the death of the Gelkis Khan and says the Maraudine are next. Warug sends you after their Khan, Hratha, and wants the piece of a key that Hratha carries. Warug wants the Maraudine Khan, Hratha, dead. A horn on a bluff in the Valley of Spears calls him out, but it will not sound without a mouthpiece, and a mouthpiece is found by killing Maraudine centaur. After the blast, Maraudine centaur gather at the tower, and Hratha shows himself in the end. Hratha holds part of a key, and Warug wants it brought to Warug in Magram Village. Warug expects you to prove yourself an ally of the Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1381-91dafc706f8fd6fb187f/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["quest:1466"] = {
  hash = "af1bad",
  fullHash = "af1bad",
  text = "Reagents for Reclaimers Inc.. Kreldig Ungor has the last of the items Leftwitch wants, and he admits it is not pretty and will take longer than the others. All of it comes from demons: brains, wings and vials of blood. Kreldig warns that the final set is a grim business, slower to gather than any before it. Leftwitch wants three kinds of parts, ten of each. The brains come from felhounds: mana eaters, mage hunters or ley hunters. The wings come from the nether maidens, sisters or sorceresses. The blood comes from doomwarder captains or lords. Kreldig says he would understand if you passed on this one. Kreldig had not even realized these demons were in Desolace. From his reading, Desolace belonged mostly to the centaur once the night elves departed years ago, and he wonders how and why the demons settled here. They dwell near Mannoroc Coven, in Desolace's south, beyond the Kodo Graveyard.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1466-0fad90a2ca02fd0520ba/1-0000.mp3", duration = 52.7412245, start = 0},
  },
}
P.transport["quest:1467"] = {
  hash = "fc6d26",
  fullHash = "fc6d26",
  text = "Reagents for Reclaimers Inc.. Kreldig Ungor gives you Leftwitch's package and sends you back to Ironforge. Roetten Stonehammer is the one to see about your pay, and Kreldig promises a kind word about you once back home. Kreldig says your pay waits in Ironforge with Roetten Stonehammer himself. Roetten will be glad to be rid of Leftwitch's package, and handing it over should be enough to get what you are owed. Kreldig expects to be in Desolace only a little longer, and still means to speak well of you once home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1467-0e16b5276ef556acaa8f/1-0000.mp3", duration = 27.7942857, start = 0},
  },
}
P.transport["quest:1488"] = {
  hash = "7fe279",
  fullHash = "7fe279",
  text = "The Corrupter. Takata Steelblade sides with Maurin: Lord Azrethoc must be stopped, especially if he seeks influence over the Burning Blade. Takata trusts you to gather a party against the demon lord and his warlock servant, Jugkar Grim'rod. Takata has never heard of Lord Azrethoc, but agrees with Maurin that the demon lord must be stopped. The danger grows if Azrethoc is trying to sway the Burning Blade. You have already shown that you want to aid the Warchief, so Takata trusts you to gather a party and slay Azrethoc and his warlock servant, Jugkar Grim'rod. Head directly south to Mannoroc Coven, where both are found. Takata calls the demons in Desolace a greater threat than ever. Each newly arrived foul creature dims the prospect of returning to the Warchief. At times, Takata wishes the centaur were the only enemy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1488-e95ba21aa198d20674ee/1-0000.mp3", duration = 48.6922449, start = 0},
  },
}
P.transport["quest:162"] = {
  hash = "b03b2e",
  fullHash = "b03b2e",
  text = "Rise of the Silithid. Senior Surveyor Fizzledowser sends you to Darnassus with a report for Gracina Spiritmight, a night elf scholar and historian. Senior Surveyor Fizzledowser wants the report in the hands of someone who knows such matters. Gracina Spiritmight is a night elf scholar and historian. She has spent much time studying life forms unique to Azeroth's ecology. Fizzledowser hopes she can judge the danger and find a way to halt it. At Fizzledowser's last word, Gracina lives in the Temple of the Moon in Darnassus.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_162-6e6e45e2961a1d96d5aa/1-0000.mp3", duration = 30.3804082, start = 0},
  },
}
P.transport["quest:193"] = {
  hash = "8682e1",
  fullHash = "8682e1",
  text = "Panther Mastery. Sir S. J. Erlgadin has set the final trial of his panther hunt before you in northern Stranglethorn Vale. Having proven your skill against the region's panthers, you are challenged to seek out Bhag'thera, an elusive predator that has so far eluded the expedition's party. Bringing back the beast's fang will establish your standing as a true master of the hunt. At Nesingwary's Expedition, Sir S. J. Erlgadin considers your trials nearly complete. One final quarry remains to prove your worth against the jungle's predators: a panther named Bhag'thera. The beast has so far eluded the expedition's own party as it prowls the wilds of Stranglethorn Vale. Erlgadin calls on you to track down this great stalker and claim the Fang of Bhag'thera as proof of your skill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_193-46ceb6002449208e31d5/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["quest:196"] = {
  hash = "50936f",
  fullHash = "50936f",
  text = "Raptor Mastery. Hemet Nesingwary raises the stakes of his hunting expedition by sending you after a elusive breed known as Jungle Stalkers. Tracking down ten of these cunning raptors will prove your mettle as a true stalker of wild beasts in Stranglethorn Vale. Having tested your aim against lesser raptors, Hemet Nesingwary presents a more demanding quarry. Jungle Stalkers are notably cagey and far more difficult to track and slay than the breeds hunted previously. Hemet expects you to venture out into the jungle, fell ten of these wary predators, and return to camp to earn a lead on his finest hunt yet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_196-3e691d61d803474e5b8b/1-0000.mp3", duration = 32.5746939, start = 0},
  },
}
P.transport["quest:197"] = {
  hash = "935841",
  fullHash = "935841",
  text = "Raptor Mastery. Deep in Stranglethorn Vale, Hemet Nesingwary challenges seasoned trackers to bring down an elusive predator that has escaped even him. Having proven your mettle against lesser beasts, you are tasked with tracking the cunning raptor known as Tethis and securing its talon. Following your earlier trials in the jungle, Hemet Nesingwary reveals the existence of a particularly vicious raptor named Tethis. While lesser hunters have chased prey across the foliage, Tethis has evaded capture entirely, defying even the expedition leader himself. Ajeck Rouack bestowed the beast with its moniker, marking it as the ultimate prize among Stranglethorn's scaled horrors. To stand recognized as a premier big game hunter, you are directed to prowl the grounds north of the Gurubashi Arena where Tethis is known to roam. Bringing back a talon from the slain terror will earn you the title of master raptor slayer, a feat no other big game hunter has accomplished.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_197-6c9e29c0a879f53d279d/1-0000.mp3", duration = 52.4016327, start = 0},
  },
}
P.transport["quest:202"] = {
  hash = "4237be",
  fullHash = "4237be",
  text = "Colonel Kurzen. Lieutenant Doren calls upon you to deliver the final strike against Colonel Kurzen and his inner guard. You are sent into the Stockpile to eliminate the rogue commander and his remaining leaders to secure the Rebel Camp's survival. Lieutenant Doren and his band of defectors have reached the climax of their struggle against their former commander. Following the suppression of Kurzen's elite specialists, Doren recognizes that the rebel forces will never truly be safe while Kurzen retains control of his jungle redoubt. He directs you into the Stockpile cave, where Kurzen directs his forces alongside his subchiefs and elites. To permanently end the threat, Doren asks for conclusive proof of Kurzen's downfall by demanding the rogue colonel's head, along with the defeat of his elites and subchiefs. Entering the cave to face Kurzen's leadership offers the rebels their sole prospect of breathing easier amid the perils of northern Stranglethorn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_202-986fbc04cc3a5e867dab/1-0000.mp3", duration = 52.48, start = 0},
  },
}
P.transport["quest:205"] = {
  hash = "39c373",
  fullHash = "39c373",
  text = "Troll Witchery. Brother Nimetz seeks insight into the corruption of Colonel Kurzen by examining dark troll enchantments. Following Kurzen's Mystery, he asks you to venture south into Skullsplitter territory and secure fetishes from their spellcasters. While reviewing the legends recovered from the jungle, Brother Nimetz turns his attention to the second troll tribe lingering further south. He suspects that dark troll sorcery may be responsible for Colonel Kurzen's descent into evil. To verify his theory, he asks you to venture into Skullsplitter lands and pry fetishes directly from their Witch Doctors and Mystics so he can study their magic at the Rebel Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_205-b26cea969cc038f9add6/1-0000.mp3", duration = 36.0228571, start = 0},
  },
}
P.transport["quest:206"] = {
  hash = "fc95d6",
  fullHash = "fc95d6",
  text = "Mai'Zoth. Brother Nimetz believes Colonel Kurzen was driven to evil by a hidden power that still lives. An ogre mage known as Mai'Zoth lurks within the eastern mountains, wielding an artifact reputed to twist and control minds. Destroying him and recovering this relic is meant to ensure no other commander suffers the same corruption. Though Kurzen has fallen, Brother Nimetz insists the primary catalyst behind the rebellion remains intact. His research points to Mai'Zoth, an ogre mage dwelling inside an ogre mound deep within the eastern heights of Stranglethorn Vale. Nimetz is certain that Mai'Zoth employed mind-altering sorcery to warp Kurzen's thoughts, warning that leaving the ogre alive invites another commander to succumb to the very same sinister influence. To permanently eliminate the threat, you are asked to strike down Mai'Zoth, take the Mind's Eye from him, and bring that corrupting artifact back to the Rebel Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_206-5dfe426a3ad2862306be/1-0000.mp3", duration = 54.5697959, start = 0},
  },
}
P.transport["quest:208"] = {
  hash = "f51de1",
  fullHash = "f51de1",
  text = "Big Game Hunter. Having proven skill across Stranglethorn Vale by hunting the region's deadliest predators, Hemet Nesingwary offers a final supreme challenge. The famed marksman asks for the head of King Bangalash, a great white tiger and the very reason Hemet is in the jungle at all. After completing the trials set by the expedition's huntsmen—slaying Sin'Dall, Bhag'thera, and Tethis—Hemet Nesingwary acknowledges your martial skill. According to the veteran marksman, who compares your prowess to the finest displays seen from Lordaeron's battlefields to the jungle depths, only one hunt remains to prove your abilities unmatched: felling King Bangalash, the grand white tiger that serves as the expedition leader's true target. Hemet reveals that King Bangalash is the reason he is in Stranglethorn Vale. The great beast has repeatedly driven the expedition leader himself back to camp in defeat. Presenting the beast's head would prove your hunting skill second to none.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_208-cfcbc0d62c30c92aa81c/1-0000.mp3", duration = 54.8832653, start = 0},
  },
}
P.transport["quest:209"] = {
  hash = "41bec1",
  fullHash = "41bec1",
  text = "Skullsplitter Tusks. Kebok in Booty Bay needs materials to meet export demands for tiger fangs destined for the South Seas. Because hunting genuine jungle predators proves too costly, he has devised an undetectable forging process using tusks harvested from the Skullsplitter trolls. Supplying tiger fangs to distant island buyers across the South Seas has grown too expensive and difficult through ordinary hunting. Rather than abandon the trade, Kebok devised an undetectable forging method that turns mundane horn-like objects into convincing replicas. The closest physical match for these fangs comes directly from the jaws of the local Skullsplitter trolls, leading Kebok to hire adventurers willing to strip eighteen tusks from the jungle tribe to fill his upcoming export shipment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_209-6c8bf8e4cf62cce0546a/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["quest:2782"] = {
  hash = "ac8ad3",
  fullHash = "ac8ad3",
  text = "Rin'ji's Secret. After helping Rin'ji, you carry Rin'ji's Secret, a tablet marked in Witherbark script that no one has read. Oran Snakewrithe studies the Witherbark and may decipher it. He is known to live in the Magic Quarter of the Undercity. Witherbark troll markings cover the tablet, but what Rin'ji's secret is remains a mystery. It may be worth a great deal or nothing at all. A Witherbark troll in trouble might try anything to escape it. Oran Snakewrithe is a well-known scholar of the Witherbark trolls. He is known to live in the Magic Quarter of the Undercity and may be able to read the tablet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2782-d965a398103d77a57c3b/1-0000.mp3", duration = 35.2130612, start = 0},
  },
}
P.transport["quest:2940"] = {
  hash = "241a05",
  fullHash = "241a05",
  text = "Feralas: A History. In Feralas, you find Feralas: A History, a book Troyas may need. It looks as if nobody has opened it in ages. The book belongs to Daryn Lightwind, so you need to ask whether you may borrow it. The book's covers are badly worn, and its pages have yellowed. After looking it over, you suspect it may be what Troyas is searching for. You pick it up, then think better of borrowing it without asking. It belongs to Daryn Lightwind, so ask her first.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2940-7fb904945a535081a407/1-0000.mp3", duration = 28.2906122, start = 0},
  },
}
P.transport["quest:2988"] = {
  hash = "e32297",
  fullHash = "e32297",
  text = "Witherbark Cages. At Witherbark Cages, you search for Sharpbeak, heir of Swiftwing, whom Talonaxe calls the mightiest gryphon. Gryphon Master Talonaxe believes the trolls took the young gryphon. Gryphon Master Talonaxe asks you to find Sharpbeak, who went missing a few days ago while hunting with his parents. Talonaxe and the others believe the trolls took him. Three cages in the two Witherbark troll villages remain to be checked. Talonaxe awaits your findings.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2988-5b98bfb6b0023dcf59f6/1-0000.mp3", duration = 27.2195918, start = 0},
  },
}
P.transport["quest:3128"] = {
  hash = "252c11",
  fullHash = "252c11",
  text = "Natural Materials. In Camp Mojache, Natural Materials are needed by Witch Doctor Uzer'i for an endeavor. The materials come from treants, mountain giants, faerie dragons, owlbeasts and hippogryphs, alongside the other trials. After you return to Witch Doctor Uzer'i, another list of materials awaits alongside the other trials. Bring two splintered logs from a Feralas treant. Mountain giants and faerie dragons westward carry six pieces of encrusted minerals. Owlbeasts in the Hinterlands or hippogryphs in Feralas provide twenty pieces of resilient sinew. Any of these creatures can yield the forty metallic fragments needed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3128-dee9e959c640328a228a/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["quest:338"] = {
  hash = "03faa7",
  fullHash = "03faa7",
  text = "The Green Hills of Stranglethorn. Barnil Stonepot was trusted to proofread the manuscript for Hemet Nesingwary's novel, but a fierce gust of wind scattered the loose pages across the jungle. To spare him his master's anger, you are asked to scour the wilds, assemble the missing pages into four complete chapters, and return the finished work. Following your arrival in the expedition camp after Welcome to the Jungle, Barnil Stonepot finds himself facing a disaster. While reviewing the draft of Hemet Nesingwary's novel, The Green Hills of Stranglethorn, a sudden gale caught the loose leaves and flung them into the wild. Though he managed to recover a fair portion of the work, many sheets remain lost in the brush. To keep his master from discovering the mishap, he needs every misplaced page tracked down and compiled into Chapter I, Chapter II, Chapter III, and Chapter IV. Bringing back the four completed sections spares Barnil from an unpleasant confrontation with Nesingwary. With the chapters gathered safely in hand, he hopes the restored work will soon find its way into libraries across the world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_338-246a5ef67e9390324b35/1-0000.mp3", duration = 61.1004082, start = 0},
  },
}
P.transport["quest:339"] = {
  hash = "ed8638",
  fullHash = "ed8638",
  text = "Chapter I. Barnil Stonepot is trying to restore the opening portion of Hemet Nesingwary's scattered hunting manuscript, The Green Hills of Stranglethorn. He needs four missing leaves gathered from across the jungle to bind the introductory section back together. Following your talk regarding The Green Hills of Stranglethorn, Barnil Stonepot sets his sights on restoring the book's opening passage. According to the dwarf, this first part sets the stage for the wider story and describes Nesingwary's hunting party, counting Barnil himself among the companions. Unfortunately, the manuscript's leaves remain lost in the wild, leaving pages one, four, six, and eight absent from the collection. Once you bring back the four missing sheets, Barnil is able to piece the first segment of the master huntsman's text back into a single, cohesive part of the book.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_339-6128ae864e36dde6f8e7/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["quest:340"] = {
  hash = "09e6d3",
  fullHash = "09e6d3",
  text = "Chapter II. Barnil Stonepot needs assistance gathering missing leaves from the second section of Hemet Nesingwary's scattered hunting manuscript. Having gathered most of the parchment himself, he relies on travelers across Stranglethorn Vale to recover the remaining scattered accounts of panther and tiger hunts. Following the dispersal of Hemet Nesingwary's manuscript across Stranglethorn Vale, Barnil Stonepot managed to reclaim many leaves on his own. The second chapter focuses entirely on thrilling accounts of tracking panthers and tigers through the wilderness. Four specific pages—numbers 10, 11, 14, and 16—remain lost to the wind and the jungle's inhabitants, leaving this section of the expedition's chronicle unfinished.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_340-a525c1cf67e416ead92c/1-0000.mp3", duration = 41.4563265, start = 0},
  },
}
P.transport["quest:341"] = {
  hash = "145bc2",
  fullHash = "145bc2",
  text = "Chapter III. Barnil Stonepot is trying to reconstruct the third chapter of Hemet Nesingwary's hunting manuscript in Stranglethorn Vale. The section recounts the first kill made with a dwarven rifle by Sir Erlgadin and Lady Rouack, but four specific leaves were blown across the jungle. Barnil Stonepot considers this portion of The Green Hills of Stranglethorn his personal favorite. The text recounts the early exploits of Sir Erlgadin and Lady Rouack, detailing their very first kill using a dwarven rifle. The chapter ends on a sharp cliffhanger. To piece the narrative together again, Barnil requires pages 18, 20, 21, and 24. These missing fragments were scattered into the wild, carried off across Stranglethorn Vale like the rest of the manuscript.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_341-34b9ff9cfad5a306d01b/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["quest:342"] = {
  hash = "e5c778",
  fullHash = "e5c778",
  text = "Chapter IV. Barnil Stonepot is trying to reconstruct the thrilling finale of Hemet Nesingwary's famous manuscript. Recovering the final three sheets will restore the climactic conclusion to the wild hunting tale. Barnil Stonepot considers this section the big finale of the entire hunting volume. To assemble the fourth chapter, he needs someone to track down and return pages twenty-five, twenty-six, and twenty-seven. Once these three lost sheets are gathered from across the jungle, the manuscript's exciting conclusion can finally be reassembled.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_342-e2e9a8e84c2e8012ec95/1-0000.mp3", duration = 29.4661224, start = 0},
  },
}
P.transport["quest:348"] = {
  hash = "35540c",
  fullHash = "35540c",
  text = "Stranglethorn Fever. In Booty Bay, Fin Fizracket lies sick with Stranglethorn Fever, a deadly virus. He says the only cure is the heart of Mokk the Savage, an elusive white beast, and that he is dying. Fin Fizracket is stammering and fading, sure that he has caught Stranglethorn Fever. He says the only cure is to eat the heart of Mokk the Savage, an elusive white beast. Witch Doctor Unbagwa is the only one who can summon the creature, and Fin sends you to find Unbagwa in a hidden cave on the southern cape, the Spirit Den.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_348-a08e4c04e2762fb51ba4/1-0000.mp3", duration = 30.72, start = 0},
  },
}
P.transport["quest:3625"] = {
  hash = "56ab55",
  fullHash = "56ab55",
  text = "Enchanted Azsharite Fel Weaponry. In Stranglethorn Vale, the master smith Galvan the Ancient works to fashion specialized armament capable of striking down powerful demons. This forging provides an enchanted weapon imbued with the Felcurse, designed specifically to weaken Razelikh the Defiler and his servitors. Galvan the Ancient requires patience while he works his craft just south of the path leading into Zul'Gurub. Rushing the forging risks creating a flawed blade, staff, or dagger. Once completed, the chosen weapon carries the power of the Felcurse, which can be unleashed periodically to weaken Razelikh the Defiler and his demonic underlings. The duration of this debilitating curse can vary.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3625-331de34767db941481ab/1-0000.mp3", duration = 39.7844898, start = 0},
  },
}
P.transport["quest:3626"] = {
  hash = "2fee61",
  fullHash = "2fee61",
  text = "Return to the Blasted Lands. With newly forged weapons in hand, you are directed back from Stranglethorn Vale to the Blasted Lands. The spirit of the Fallen Hero of the Horde awaits your return to set you against the demon Razelikh. Following the completion of your enchanted armaments, Galvan the Ancient proclaims that the hour of redemption is at hand. You carry the newly crafted weapons back to the Blasted Lands, seeking out the Fallen Hero of the Horde. The ghostly warrior asks whether you are prepared to face Razelikh and his minions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3626-29ff8402d665be1a0959/1-0000.mp3", duration = 27.6114286, start = 0},
  },
}
P.transport["quest:4130"] = {
  hash = "a4341f",
  fullHash = "a4341f",
  text = "Psychometric Reading. After Psychometric Reading, Quintis Jonespyre is still unsteady. His vision shows Raschal and the Woodpaw gnolls, and Quintis asks you to carry word to Ginro Hearthkindle in Feathermoon Stronghold. Quintis Jonespyre is unsteady, but his vision may help. Raschal pulls two large leather backpacks from the boat, heads inland, then returns to the boat. Gnoll scalps appear, and Quintis believes Raschal met Woodpaw gnolls. Raschal is very worried, almost terrified, and does not notice water elementals forming behind him. Then the images end. Quintis needs rest, so he asks you to tell Ginro, who needs to know.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4130-596febd87588c832842b/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["quest:507"] = {
  hash = "8e50c3",
  fullHash = "8e50c3",
  text = "Lord Aliden Perenolde. Krusk wants Lord Aliden Perenolde dead, and the Warchief's pendant recovered. Perenolde's manor lies north, on Lordamere Lake; his mistress Elysa knows about the pendant. After Blackmoore's Legacy, Krusk says Perenolde must die and his foulness be ended. His manor lies north, on the shores of Lordamere Lake at Dandred's Fold. Once the deed is done, ask his mistress Elysa about Taretha's pendant, which the Warchief desires.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_507-f709c107e5106eb3f57c/1-0000.mp3", duration = 27.3240816, start = 0},
  },
}
P.transport["quest:508"] = {
  hash = "cd2e25",
  fullHash = "cd2e25",
  text = "Taretha's Gift. Elysa gives up Taretha's Gift and asks for peace. After the step with Lord Aliden Perenolde, you carry the pendant to Krusk in Tarren Mill. Elysa wants no memory of Lord Aliden Perenolde. She gives you the pendant and asks only to be left in peace. It once belonged to Taretha Foxton, Thrall's childhood friend. You carry it to Krusk in Tarren Mill, returning it to the orcs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_508-0ec68456192cf672518e/1-0000.mp3", duration = 24.5812245, start = 0},
  },
}
P.transport["quest:519"] = {
  hash = "a54b6d",
  fullHash = "a54b6d",
  text = "The Crown of Will. In Tarren Mill, Melisara seeks the heads of three ogres before Mug'Thol. Melisara names Targ, Muckrake and Glommus as Mug'Thol's loyal lieutenants, though she wonders what could make an ogre loyal. You are to kill all three and bring their heads to Tarren Mill. Then only Mug'Thol's head, crown and all, remains to be taken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_519-538268c90850d8ffad1f/1-0000.mp3", duration = 19.8791837, start = 0},
  },
}
P.transport["quest:520"] = {
  hash = "40495d",
  fullHash = "40495d",
  text = "The Crown of Will. With Mug'Thol's lieutenants dead, Melisara in Tarren Mill sends you after him. Bring back his head and the Crown of Will, and the Crushridge resistance will be over. Only Mug'Thol remains. Melisara expects him to resist giving up the Crown of Will. After his lieutenants fell, he likely expects you. Find him, kill him, and bring his head and the Crown back to Tarren Mill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_520-05e735738fc9adea451d/1-0000.mp3", duration = 23.3273469, start = 0},
  },
}
P.transport["quest:521"] = {
  hash = "7e9b4f",
  fullHash = "7e9b4f",
  text = "The Crown of Will. Only one step remains: the Crown is bound for Sharlindra in the Undercity, who will see that it reaches Lady Sylvanas. Melisara sends you to take the Crown to Sharlindra in the Undercity, where she will pass it on to Lady Sylvanas. She warns you not to use it for your own purposes. Mug'Thol's fate is warning enough.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_521-31397ee7c0db3acec864/1-0000.mp3", duration = 18.8342857, start = 0},
  },
}
P.transport["quest:566"] = {
  hash = "705345",
  fullHash = "705345",
  text = "WANTED: Baron Vardus. In Tarren Mill, High Executor Darthalia calls for Baron Vardus's death. The human is a high-ranking member of the Syndicate, wanted for crimes against the Forsaken; bring proof of his death to Darthalia. High Executor Darthalia has put a price on Baron Vardus, a human accused of crimes against the Forsaken and counted among the Syndicate's high-ranking members. The last word placed him in the Uplands of the Alterac Mountains, north of Tarren Mill. Darthalia's order calls for his death, and payment awaits whoever brings her proof. Baron Vardus may be at any of the Syndicate camps across the Uplands. He may also be hiding in the cellar of the inn at Strahnbrad.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_566-5aa6e33f4067277602b1/1-0000.mp3", duration = 39.2881633, start = 0},
  },
}
P.transport["quest:571"] = {
  hash = "b31492",
  fullHash = "b31492",
  text = "Mok'thardin's Enchantment. Far Seer Mok'thardin in Grom'gol Base Camp needs a sturdy magical binding to hold together the Stranglethorn trophies collected so far. To bind the feathers, claws, and fang securely, he requires an aged sinew harvested from the elder primates roaming southern Stranglethorn Vale. Having gathered feathers, claws, and a pristine fang, Far Seer Mok'thardin reaches the next stage of his ritual. To fasten these potent relics together, he requires a magical tether of exceptional toughness. Only the aged sinew of an Elder Mistvale Gorilla will suffice to endure the magic he intends to weave. The beasts carrying the necessary sinew forage in the jungles east of Booty Bay. Mok'thardin warns that only a flawless sinew will do, meaning hunters may need to track and fell several of the elder gorillas before securing a specimen fit for the enchantment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_571-a3932b7012db7f125353/1-0000.mp3", duration = 47.5428571, start = 0},
  },
}
P.transport["quest:572"] = {
  hash = "1109ce",
  fullHash = "1109ce",
  text = "Mok'thardin's Enchantment. Far Seer Mok'thardin continues assembling the components for a potent shamanistic item to aid the Horde. After working with feline trophies, he turns his attention toward the feathers worn by the raptors of Stranglethorn Vale. Following the recovery of materials from the jungle's feline predators, Far Seer Mok'thardin reveals that more components are needed before his shamanistic ritual can begin. To forge a tool fit to assist the Warchief, he requires feathers worn by Jungle Stalkers. These raptors inhabit the dense jungle south of Grom'gol Base Camp, not far from the great arena.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_572-30f1b1b2d5d4b58f5c5f/1-0000.mp3", duration = 32.6530612, start = 0},
  },
}
P.transport["quest:573"] = {
  hash = "7e9041",
  fullHash = "7e9041",
  text = "Mok'thardin's Enchantment. Far Seer Mok'thardin requires one final sacred component to complete the enchantment of a ceremonial choker at Grom'gol Base Camp. He directs you to an elevated Holy Spring along the southern bluffs near the western sea, which has drawn the attention of a hostile naga expedition. Following the earlier stages of Mok'thardin's enchantment, the far seer seeks water from a Holy Spring situated high above the bluffs in the southern reaches of Stranglethorn Vale, near the western coast. The site is a point of contention among scholars of the mystic and divine, with every race across Azeroth claiming the holy waters were sanctified specifically for their own people. A party of naga explorers has moved up to the spring and must be dealt with as well. Mok'thardin requires ten of these serpent intruders slain alongside a draught of the spring water to finish preparing the ceremonial choker in the name of the Warchief.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_573-100fb83ca2d6cd3f615c/1-0000.mp3", duration = 51.8530612, start = 0},
  },
}
P.transport["quest:580"] = {
  hash = "2d8a92",
  fullHash = "2d8a92",
  text = "Whiskey Slim's Lost Grog. In the pirate haven of Booty Bay, Whiskey Slim finds himself in dire trouble with his captain. During a violent storm off the coast of the Hinterlands, Slim tapped into a seized crate of Pupellyverbos Port, only to lose the bottles to the churning sea. To escape a brutal flogging, he needs an adventurer to retrieve his misplaced grog. Whiskey Slim's crew was battling severe weather off the Overlook Cliffs, with the shore of the Hinterlands looming nearby, when the sailor sought a dose of liquid courage. His ship had seized a crate of Pupellyverbos Port from a privateer vessel sailing toward Stormwind. Facing waves that threatened to swallow their ship whole, Slim broke into the captain's crate, but a sudden surge swept the bottles right over the side. Back in Booty Bay, the clock is ticking down as the ship prepares to weigh anchor. Slim dreads facing the cat-o'-nine-tails once his commanding officer realizes the confiscated port is missing. He seeks someone willing to bring back twelve bottles before his theft comes to light.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_580-4946f31d61052559b074/1-0000.mp3", duration = 59.5853061, start = 0},
  },
}
P.transport["quest:584"] = {
  hash = "1b9dd2",
  fullHash = "1b9dd2",
  text = "Bloodscalp Clan Heads. Following the sorting of trophies gathered in the jungle, Nimboya confirms that the missing young troll Yenniku was not among them. To discover the truth of Yenniku's fate, the Darkspear seek to compel answers from the leaders of the rival Bloodscalp tribe. After the earlier hunt proved Yenniku was not among the fallen Bloodscalp trophies, Nimboya looks to higher leadership for answers. The Bloodscalp chief, Gan'zulah, and his witch doctor, Nezzliok the Dire, are enemies of the Darkspear tribe and would never talk willingly. Nimboya means to force the truth from their dead lips, bringing their heads to the cauldron at Grom'gol Base Camp to make them talk. Both Bloodscalp leaders dwell deep within the ruins of Zul'Kunda in northwestern Stranglethorn Vale. Claiming their heads and casting them into the boiling brew is how Nimboya means to make them talk about Yenniku.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_584-6786645eda0ab1960193/1-0000.mp3", duration = 50.4946939, start = 0},
  },
}
P.transport["quest:585"] = {
  hash = "9875f0",
  fullHash = "9875f0",
  text = "Speaking with Nezzliok. After defeating the Bloodscalp witch doctor, his severed head speaks from the bubbling cauldron at Grom'gol Base Camp. He claims to know where the lost Darkspear child was taken, but he refuses to give up the secret without a grim tribute. Though bound within the bubbling cauldron following the hunt for Bloodscalp Clan Heads, Nezzliok is far from cooperative. He admits knowing where Yenniku was taken, yet he demands appeasement before parting with the information. He commands that three trophy skulls be taken from the rival Skullsplitter tribe and brought to his resting place, ensuring his departed spirit will command thralls in the Nether. Nezzliok demands one skull taken directly from the Skullsplitter trophy pile at Balia'mah, a second from Ziata'jai, and a third from Zul'Mamwe. Only when all three offerings rest alongside his own head will the dead witch doctor consider his spirit satisfied.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_585-fd745fc49cfe65eef733/1-0000.mp3", duration = 50.8081633, start = 0},
  },
}
P.transport["quest:586"] = {
  hash = "cb0c9d",
  fullHash = "cb0c9d",
  text = "Speaking with Gan'zulah. Even after losing his head to the boiling brew at Grom'gol Base Camp, the Bloodscalp chieftain Gan'zulah seethes with fury. To appease his lingering rage, the severed spirit demands the death of his bitter Skullsplitter rivals and the ruin of their ruler, Ana'thek the Cruel. Following the collection of the Bloodscalp Clan Heads, Gan'zulah's severed head continues to curse anyone standing over the bubbling pot. Consumed by hatred for both his captors and his ancestral enemies, the dead chieftain offers an avenue to quiet his boiling temper: an assault into the eastern stronghold of the Skullsplitter tribe. He demands a slaughter of their hunters, headhunters, and berserkers, daring travelers to perish against their ferocious warband. Gan'zulah expects the assault to end in disaster, fully anticipating that Chief Ana'thek the Cruel will tear apart any intruder who dares challenge him. He demands nothing less than the shattered armor stripped from the Skullsplitter ruler himself as proof of triumph. Only bearing this trophy back to the cauldron in Grom'gol Base Camp can satisfy the dead chieftain's spite.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_586-81d42055bfb94ce671a5/1-0000.mp3", duration = 64.3134694, start = 0},
  },
}
P.transport["quest:588"] = {
  hash = "f2d57f",
  fullHash = "f2d57f",
  text = "The Fate of Yenniku. At Grom'gol Base Camp, the head of Nezzliok speaks from the bubbling cauldron, ready to tell what became of the young Darkspear troll Yenniku. Kin'weelay stands beside the pot, waiting to hear the spirit's words. Having placated the spirits of Gan'zulah and Nezzliok, you listen as the head within the bubbling cauldron finally imparts its secret. Kin'weelay stands right beside the cauldron, waiting to hear it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_588-ee0f3cffd449d4c1216b/1-0000.mp3", duration = 24.0326531, start = 0},
  },
}
P.transport["quest:589"] = {
  hash = "3534ba",
  fullHash = "3534ba",
  text = "The Singing Crystals. Kin'weelay seeks a way to rescue young Yenniku from the darkness that has claimed him. Following the revelation of Yenniku's plight, the witch doctor plans to locate a legendary jewel known as the Mind's Eye, sending you to gather resonance shards needed to master its power. After learning the grim fate that befell Yenniku, the medicine man Kin'weelay turns to ancient jungle lore for an answer. Tales speak of the Mind's Eye, a gem hidden within the depths of Stranglethorn that possesses immense magical strength. Kin'weelay believes this stone could hold the secret to freeing the young troll's spirit. While he communally seeks the guidance of the jungle spirits to pinpoint its location, he needs rare catalysts to safely command the jewel's potent sorcery. Kin'weelay directs you southeast toward Crystalvein Mine, where ironjaw basilisks dwell beneath the earth. From these creatures, you are to recover three pulsing blue shards. Kin'weelay intends to channel the inherent magic of these singing stones in a concluding ritual, bending the raw might of the Mind's Eye to his command once the gem is recovered.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_589-0f5e6951fb400b0974ba/1-0000.mp3", duration = 65.044898, start = 0},
  },
}
P.transport["quest:591"] = {
  hash = "1c016e",
  fullHash = "1c016e",
  text = "The Mind's Eye. Kin'weelay at Grom'gol Base Camp seeks a powerful gem known as the Mind's Eye, an artifact essential for rescuing young Yenniku. The stone rests in the hands of the formidable ogre spellcaster Mai'Zoth, who dwells deep within the Mosh'Ogg Ogre Mound. Following the recovery of the singing crystals, Kin'weelay turns his attention toward securing the Mind's Eye. This potent artifact is the solitary instrument capable of aiding the rescue of Yenniku, the son of the Darkspear chieftain. However, the stone is currently held by Mai'Zoth, a ruthless ogre mage whose presence Kin'weelay remembers from the tribe's earlier days in the jungle. Mai'Zoth resides deep inside the Mosh'Ogg Ogre Mound to the east of Grom'gol. His magical prowess was formidable even before acquiring the Mind's Eye, and the stone has only amplified his strength. Confronting him amidst the ogre stronghold is fraught with peril, but wresting the artifact from his grasp remains the sole hope of freeing the young troll.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_591-74c4702dad6e3aa8d993/1-0000.mp3", duration = 58.4620408, start = 0},
  },
}
P.transport["quest:592"] = {
  hash = "c79d90",
  fullHash = "c79d90",
  text = "Saving Yenniku. After obtaining the Mind's Eye, Kin'weelay crafts it into a specialized soul gem to rescue the young troll Yenniku from Zanzil the Outcast. The enchanted vessel is designed to stun Yenniku and capture his spirit, allowing him to be freed and carried back to Nimboya. Following the recovery of the Mind's Eye, Kin'weelay reshapes the potent relic into a magical soul gem. Its dual enchantment allows an adventurer to first stun Yenniku and then place the stone upon his head to capture his wayward spirit within. Once the boy's essence is contained inside the gem, it can safely be returned to his kin at Grom'gol Base Camp. Yenniku resides alongside Zanzil the Outcast within the Ruins of Aboraz, situated along the Crystal Shore on the southern reaches of the Cape of Stranglethorn. Reaching the fallen youth requires venturing into Zanzil's territory, using the crafted vessel to break the witch doctor's hold over him, and carrying the filled gem back to Nimboya.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_592-d04077712e90472763d1/1-0000.mp3", duration = 55.1967347, start = 0},
  },
}
P.transport["quest:593"] = {
  hash = "bc49c6",
  fullHash = "bc49c6",
  text = "Filling the Soul Gem. Deep in the jungle of Stranglethorn Vale, an attempt is made to preserve the young troll Yenniku. With the youth caught in a trance, a prepared soul gem is brought forth to capture his spirit. Following the effort to save Yenniku, you stand face to face with the young troll in Stranglethorn Vale. His mind is lost, caught entirely in another place while he remains motionless before you. The only path forward involves the enchanted gem prepared specifically to hold his essence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_593-70cf37136d8beff2bc5f/1-0000.mp3", duration = 27.0628571, start = 0},
  },
}
P.transport["quest:594"] = {
  hash = "ebd2a4",
  fullHash = "ebd2a4",
  text = "Message in a Bottle. A washed-up bottle found along the shores of Stranglethorn Vale holds an urgent plea for rescue. Its author claims to be held prisoner by a great beast on an isolated island in the South Seas. Inside a glass container half-buried in the sand lies a neatly penned note asking for immediate assistance. The captive reports being trapped on a foreign island beneath thick jungle canopies, held by a great Skymane. Glimpses through the trees offer only faint landmarks: the coast of Wild Shore lies visible to the northwest, while large sailing vessels drift to the southwest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_594-54dfd1aa81cac9917558/1-0000.mp3", duration = 34.4293878, start = 0},
  },
}
P.transport["quest:595"] = {
  hash = "3b4503",
  fullHash = "3b4503",
  text = "The Bloodsail Buccaneers. First Mate Crazz of the Blackwater Raiders needs an adventurer to investigate rumors of rival pirates. With his crew busy drinking and chasing company in Booty Bay, he asks you to scout a nearby cove along the Savage Coast for signs of the Bloodsail Buccaneers. The Blackwater Raiders have newly docked in Booty Bay, only to hear word that their rivals, the Bloodsail Buccaneers, have been sighted across southern Stranglethorn Vale. With the rest of the crew distracted by grog and shoreline pursuits, First Mate Crazz turns to an outsider for help. He asks you to head north along the Savage Coast and scout a cove to see what the Bloodsail Buccaneers are up to.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_595-1eb915b4a0e87e65db9c/1-0000.mp3", duration = 38.3216327, start = 0},
  },
}
P.transport["quest:597"] = {
  hash = "efdf0f",
  fullHash = "efdf0f",
  text = "The Bloodsail Buccaneers. At Booty Bay, the Bloodsail Buccaneers’ plans now point to a camp and an attack signal. A map marks the Bloodsail Buccaneers’ intended camp in Booty Bay with a red X. Their orders call for silence. The crew must kill anyone who approaches and wait for a signal from the southern command post before attacking. You carry the findings back to First Mate Crazz in Booty Bay. He sent you to scout, and the pirates are still waiting for the signal before they attack.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_597-d7c71aca244876258d37/1-0000.mp3", duration = 28.4212245, start = 0},
  },
}
P.transport["quest:598"] = {
  hash = "7298ac",
  fullHash = "7298ac",
  text = "Split Bone Necklace. Kin'weelay at Grom'gol Base Camp calls upon Horde allies to hunt the Skullsplitter tribe living to the southeast. Although the Darkspears left Stranglethorn Vale behind, their ancient conflict with these jungle rivals remains unresolved. Returning with twenty-five split bone trophies aids the Darkspears in their war and earns their friendship. Following the collection of Bloodscalp trophies, Kin'weelay turns his attention toward another longstanding enemy. The Skullsplitter tribe dwells to the southeast of Grom'gol Base Camp, where they have clashed with the Darkspears across many years. Even though the Darkspears no longer reside within the jungles of Stranglethorn Vale, they remain bound to this enduring war. To earn the friendship and respect of the Darkspear tribe, an adventurer must march into Skullsplitter territory and claim twenty-five of their distinctive split bone necklaces. Kin'weelay takes pride in seeing these hostile trolls cut down like young saplings by a basilisk, counting every retrieved trophy as a victory for his people.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_598-a850c917cb98c9b85fe5/1-0000.mp3", duration = 60.3167347, start = 0},
  },
}
P.transport["quest:599"] = {
  hash = "08bd1b",
  fullHash = "08bd1b",
  text = "The Bloodsail Buccaneers. First Mate Crazz has learned that the Bloodsail Buccaneers intend to launch an assault against Booty Bay. The scale of the threat demands the attention of the Blackwater Raiders' commander, Fleet Master Seahorn, who needs to hear the warning immediately. Upon discovering that the Bloodsail Buccaneers scheme to strike Booty Bay directly, First Mate Crazz decides it is bigger than he thought. He directs you to seek out Fleet Master Seahorn, who is somewhere in the port town, and inform him of the brewing assault before the rival pirates can make their move.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_599-f347b222237bdd10ed00/1-0000.mp3", duration = 29.7012245, start = 0},
  },
}
P.transport["quest:600"] = {
  hash = "73d40f",
  fullHash = "73d40f",
  text = "Venture Company Mining. In Booty Bay, the goblin Crank Fizzlebub wants someone to strike at the Venture Company's operations in northern Stranglethorn Vale. Their dig site near Crystalvein Mine continues to produce valuable Singing Blue Crystals from the nearby hills, and Crank asks for ten of those stones brought back to him. Following your earlier collection of Singing Blue Shards, Crank Fizzlebub points toward a larger rival. The Venture Company runs operations across the jungle, cutting into the profits of independent goblins. Though the many basilisks keep the miners from setting foot inside Crystalvein Mine itself, the workers continue digging into the surrounding hillsides to extract Singing Blue Crystals. Crank asks you to take the crystals from these miners and bring them to Booty Bay as proof of their setback.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_600-cafcc10dd140d8106c44/1-0000.mp3", duration = 43.6244898, start = 0},
  },
}
P.transport["quest:604"] = {
  hash = "b5040b",
  fullHash = "b5040b",
  text = "The Bloodsail Buccaneers. Fleet Master Seahorn trusts a loyal ally of the Blackwater Raiders with striking the Bloodsail Buccaneers' so-called southern command post on the Wild Shore. Recovering their charts and written orders will show exactly what those pirates are up to. Following earlier efforts for Crazz, Fleet Master Seahorn takes notice of your loyalty to the Blackwater Raiders. The Bloodsail Buccaneers have set up what they call a southern command post on the Wild Shore. Seahorn directs you to raid this encampment, cut down their swashbucklers, and seize their naval charts and written orders so the fleet can learn their intentions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_604-15549ce6d92b3ea35c46/1-0000.mp3", duration = 34.324898, start = 0},
  },
}
P.transport["quest:608"] = {
  hash = "27f247",
  fullHash = "27f247",
  text = "The Bloodsail Buccaneers. In Stranglethorn, the Bloodsail Buccaneers gather strength for an attack. Fleet Master Seahorn will not risk his whole fleet in a counterstrike, so he sends a small crew against their leaders before they can begin. Fleet Master Seahorn means to halt the Bloodsail attack before it gains strength. He mocks Fleet Master Firallon's skill at sea, then chooses to strike at the commanders. Seahorn will not risk a full naval battle. Instead, he sends a small crew to Firallon's landing camp to kill Firallon, Captain Stillwater, and Captain Keelhaul. Without their leaders, the buccaneers will be left without command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_608-8cc800e1f5fac77bc5c8/1-0000.mp3", duration = 36.9893878, start = 0},
  },
}
P.transport["quest:609"] = {
  hash = "49a622",
  fullHash = "49a622",
  text = "Voodoo Dues. \"Sea Wolf\" MacKinley in Booty Bay needs to balance his books by collecting outstanding debts from three old associates. Though rumors claim the men were cursed and bewitched into wandering ancient jungle ruins, MacKinley expects their prized possessions retrieved regardless of their grim fate. Following your earlier collection efforts for \"Sea Wolf\" MacKinley, the pirate still holds an active ledger of unsettled debts. Three particular debtors—Maury \"Club Foot\" Wilkins, Jon-Jon the Crow, and Chucky \"Ten Thumbs\"—have let their accounts sit delinquent for months. MacKinley initially assumed the trio merely skipped out of Booty Bay to avoid paying, but he later heard they met a stranger and darker fate deep in the jungle. Whispers say the three debtors were bewitched and cursed, leaving them to wander the ancient stonework northeast of Booty Bay at the Ruins of Aboraz and the Ruins of Jubuwal. Unconcerned with their misfortune, MacKinley directs you to venture into the ruins, track down each man, and seize their notable valuables: Jon-Jon's Golden Spyglass, Chucky's Huge Ring, and Maury's Clubbed Foot.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_609-baf27bcebcef0e0fe7d9/1-0000.mp3", duration = 63.6342857, start = 0},
  },
}
P.transport["quest:611"] = {
  hash = "eee77c",
  fullHash = "eee77c",
  text = "The Curse of the Tides. With her knife recovered from Pretty Boy Duncan, Catelyn the Blade loans the troll artifact so it can be used against a sunken altar off the coast. Baron Revilgaz in Booty Bay wants the Stone of the Tides for his collection of ancient troll artifacts. Catelyn the Blade lends her recovered troll dagger to break an altar submerged deep beneath the waves. Though no expert on troll ruins like her father, she has heard of a sunken troll city, and she points toward it, out near the reef northwest of Grom'gol Base Camp. Within the underwater ruins of the Vile Reef, the Altar of the Tides rests, surrounded by a distinct blue glow amid sea life and murlocs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_611-5cd04b31063a9831e305/1-0000.mp3", duration = 37.7730612, start = 0},
  },
}
P.transport["quest:613"] = {
  hash = "6f2945",
  fullHash = "6f2945",
  text = "Cracking Maury's Foot. \"Sea Wolf\" MacKinley has retrieved the foot of his late debtor Maury, only to find that what he is owed is locked inside it. To claim what is owed, he directs travelers to the Mosh'Ogg ogre mound in Stranglethorn Vale to search for the missing key. Following the retrieval of Maury's foot in Voodoo Dues, \"Sea Wolf\" MacKinley faces an unexpected complication in Booty Bay. The late debtor put a lock on his foot, and the valuables he owes are sealed inside. Maury liked to gamble with the ogres of the Mosh'Ogg mound, off to the northeast. MacKinley remembers Maury saying the ogres drove him away once he had won too much, so he suspects they now hold the key and sends travelers to look for it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_613-4139ac56af4b2582deca/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["quest:617"] = {
  hash = "a0416a",
  fullHash = "a0416a",
  text = "Akiris by the Bundle. Privateer Bloads in Booty Bay is looking to acquire bundles of valuable akiris reeds for an associate named Groy. The plants have to be taken from the naga, who were last spotted on the northern beach. Privateer Bloads offers work in Booty Bay for anyone willing to tackle a seaside venture. An associate named Groy pays handsomely for bundles of akiris reed, a reed that grows by the sea and that the naga call by that name. Bloads does not know why Groy wants them, only that ten stalks are needed and that the naga were last spotted on the northern beach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_617-b14b0bcd5dc825880cca/1-0000.mp3", duration = 32.4963265, start = 0},
  },
}
P.transport["quest:618"] = {
  hash = "ba7a2b",
  fullHash = "ba7a2b",
  text = "Facing Negolash. Following the trail of Captain Hecklebury Smotts' lost weapon, Sprogger reveals a plan to bait the giant Negolash using the creature's favorite delicacies. By staging a banquet in a wrecked lifeboat on the coast of Stranglethorn Vale, adventurers can confront the brute and reclaim the captain's stolen cutlass. When giants smashed Captain Smotts' vessel, one brute named Negolash headed straight for the galley. Unlike his brethren, he wasn't hungry for the crew. Sprogger saw that Negolash wanted wine and Barbecued Buzzard Wings, Sprogger's own specialty, whose recipe he had to travel to the Badlands to get. To lure the giant, Sprogger devises an irresistible feast. Adventurers must haul ten helpings of the wings alongside five bottles of wine into the captain's ruined lifeboat down the southeastern shoreline. Drawn by the smell of the banquet, Negolash can be cornered, slain, and stripped of the captain's prize blade.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_618-c1d27ca83664db2d8447/1-0000.mp3", duration = 55.275102, start = 0},
  },
}
P.transport["quest:619"] = {
  hash = "3dbfab",
  fullHash = "3dbfab",
  text = "Enticing Negolash. Along the shores of Stranglethorn Vale rests an abandoned lifeboat marked with the faded words Smotts' Revenge. Piling barbecued buzzard wings and junglevine wine upon the wrecked craft serves to lure out the giant Negolash. The wreckage of a small boat lies neglected, carrying only weathered lettering that names it Smotts' Revenge. To catch the attention of Negolash during the hunt against him, the boat must be turned into bait, heaped with ten barbecued buzzard wings and five bottles of junglevine wine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_619-a0f5d08006c3f3a663a2/1-0000.mp3", duration = 30.484898, start = 0},
  },
}
P.transport["quest:621"] = {
  hash = "21d5f0",
  fullHash = "21d5f0",
  text = "Zanzil's Secret. In Booty Bay, the goblin Crank Fizzlebub has set his sights on the potent concoction brewed by the exiled troll Zanzil. Zanzil uses this botanical blend to dominate the minds and empower the bodies of his followers among the nearby jungle ruins. Believing such a substance holds immense value for anyone seeking to control others, Fizzlebub wants samples retrieved for his own uses. Northeast of Booty Bay, the outcast troll known as Zanzil has made a haven in the ruins of Jubuwal and Aboraz. Cast out by his former tribal leaders because they feared his mastery over the minds of others, Zanzil commands a band of followers entirely through concoctions derived from jungle vegetation. These mixtures deaden their will while enhancing their physical might, turning them into docile yet sturdy thralls. Crank Fizzlebub sees clear opportunity in the exile's craft. Anyone desiring dominance over others would pay handsomely for such an elixir, prompting the goblin to seek a supply directly from the ruins. Delivering enough samples secures not only standard coin but a quiet bonus, provided the carrier keeps quiet about the transaction.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_621-7c7fd6a1a7ed5e24ad3a/1-0000.mp3", duration = 66.9518367, start = 0},
  },
}
P.transport["quest:623"] = {
  hash = "4e1bfd",
  fullHash = "4e1bfd",
  text = "Akiris by the Bundle. Privateer Bloads in Stranglethorn Vale needs a fresh bundle of akiris reeds transported across the sea to Dustwallow Marsh. A contact named Privateer Groy has a client in Theramore Isle who wants more right away, and Bloads himself will not be heading there for a week. Word has arrived from across the sea while you were away. Privateer Groy in Theramore Isle sent word to Privateer Bloads expressing satisfaction with the prior shipment of akiris reeds, noting that an interested client demands more immediately. With Bloads not scheduled to sail for Dustwallow Marsh for another week, he entrusts you with the packaged parcel of reeds to deliver by hand.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_623-30e45e54b852a6acd6d4/1-0000.mp3", duration = 35.9183673, start = 0},
  },
}
P.transport["quest:624"] = {
  hash = "ee2df2",
  fullHash = "ee2df2",
  text = "Cortello's Riddle. A hidden parchment found aboard the Bloodsail Buccaneer vessels along the Wild Shore presents Cortello's cryptic verse. Deciphering the poem points travelers toward a clue waiting beneath an ornate bridge. Scattered notes aboard the Bloodsail fleet anchored off the southern coast of Stranglethorn Vale carry a rhyme. Cortello's verse describes a finely worked, much-used bridge that lies east of Deadwind and south of Redridge. Anyone seeking to unravel the mystery must follow these poetic directions out of the jungle and into the marshes to find what waits underneath.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_624-6d2aac032ebe90691430/1-0000.mp3", duration = 31.2946939, start = 0},
  },
}
P.transport["quest:625"] = {
  hash = "332091",
  fullHash = "332091",
  text = "Cortello's Riddle. Following the trail begun with a waterlogged parchment found in the Swamp of Sorrows, a second cryptic verse urges travelers to a far-off land in Kalimdor. Deciphering the lines points treasure hunters toward a cave in the southwest of Dustwallow Marsh. The second verse left by Cortello directs searchers toward the far-off land of Kalimdor. The rhyme describes a perilous and gloomy territory situated east of the Barrens: the sodden, treacherous wetlands of Dustwallow Marsh. According to the riddle, a clue waits to be found in a cave in the southwest of the marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_625-1eda3180f0a395b75782/1-0000.mp3", duration = 32.8881633, start = 0},
  },
}
P.transport["quest:626"] = {
  hash = "f8025b",
  fullHash = "f8025b",
  text = "Cortello's Riddle. A cryptic musty scroll provides the final set of verse left behind by Cortello. The rhyming instructions direct treasure hunters far north to the troubled continent of Lordaeron, where the trail reaches its conclusion along the coastal waterfalls of the Hinterlands. Following the earlier scrolls, this weathered text points away from the southern tropics toward the embattled lands of Lordaeron. The riddle bids searchers to seek out the great turmoil in the north, promising that the long chase ends by braving that unrest and pursuing the coastline. The verse specifies that the final hoard lies along the shore of the Hinterlands. At the base of the great falls, the treasure lies underwater.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_626-39b0134b45080624846e/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["quest:630"] = {
  hash = "579580",
  fullHash = "579580",
  text = "Message in a Bottle. Having answered an ocean-borne plea, you find Princess Poobah chained as a captive on an isolated island off the Stranglethorn coast. The monstrous ape King Mukla commands the local beasts and keeps her bound, requiring his defeat to secure the key to her shackle. Following the message in the bottle brings you directly to Princess Poobah, who is held against her will by a heavy chain. The great Skymane gorilla known as King Mukla commands the creatures roaming the island and oversees her imprisonment. Poobah places her faith in you to face this formidable ape and retrieve the key needed to sever her bonds. Poobah notes that her captor can often be heard prowling around the southeastern side of the island. Confronting King Mukla is no small feat, but taking him down is the only way to claim the shackle key and secure Poobah's release.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_630-4638fc89465759467f5c/1-0000.mp3", duration = 45.6881633, start = 0},
  },
}
P.transport["quest:640"] = {
  hash = "322ebc",
  fullHash = "322ebc",
  text = "The Broken Sigil. After you took the first sigil from the Syndicate, Zengu sends you after the remaining two, which the dug-in Stromgarde militia guards. Galen, son of Thoras Trollbane, broke the Sigil of Thoradin into pieces, and you are to carry them to the troll shaman Tor'gan in Hammerfall. Three sigils guard the tomb of Thoras Trollbane, and you have already recovered the first from the Syndicate. The other two are harder to get, since the firmly entrenched Stromgarde militia holds them. Thoras' son, Galen, divided the Sigil of Thoradin into eleven pieces and dispersed them among the Stromgarde defenders. Zengu tells you to retrieve the pieces from the defenders in Stromgarde and take them to Tor'gan, the troll shaman at Hammerfall, who can bind them into the whole sigil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_640-8ff6d6e24dda62f54b2e/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["quest:641"] = {
  hash = "fc914d",
  fullHash = "fc914d",
  text = "Sigil of Thoradin. Tor'gan's reconstruction of the broken sigil worked flawlessly. The restored Sigil of Thoradin can now open the seal on Trollbane's tomb, and he tells you to return it to Zengu in Hammerfall. Tor'gan says the reconstruction worked flawlessly, and the Sigil of Thoradin is now able to open the seal on Trollbane's tomb. Take it back to Zengu in Hammerfall, who no doubt has more for you to do.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_641-1af4ab8135db2bf39f70/1-0000.mp3", duration = 21.3942857, start = 0},
  },
}
P.transport["quest:643"] = {
  hash = "587912",
  fullHash = "587912",
  text = "Sigil of Arathor. Following the Sigil of Thoradin, Zengu tells you the human prince entrusted another sigil to Lieutenant Valorcall, who commands the cavalry. Find him, and bring the sigil back to Zengu in Hammerfall. Zengu scoffs that the humans can scarcely call Stromgarde their own, never mind the whole of the Arathi Highlands, yet their prince keeps the last of his horsemen riding about the countryside. Zengu cannot understand why. More important is that one of the sigils rests with Lieutenant Valorcall, who leads those riders. Zengu wants him found and the sigil brought back to Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_643-ee6a7b4711500822a46e/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["quest:644"] = {
  hash = "eb1c0e",
  fullHash = "eb1c0e",
  text = "Sigil of Trollbane. Following the Sigil of Arathor, Zengu sends you to slay Prince Galen Trollbane and take the last sigil, the one that unlocks his father Thoras Trollbane's tomb. The prince keeps it on his own person, far inside Stromgarde. The last sigil that can open the tomb of Thoras Trollbane is kept by Thoras's son, Prince Galen, in person. He is to be found far inside Stromgarde, in a chapel within the districts the militia holds. Zengu warns that Galen is well guarded and a fine fighter, so this could prove very hard. You are to kill him and carry the sigil to Zengu in Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_644-c2262b3b089fc5c0e715/1-0000.mp3", duration = 34.4032653, start = 0},
  },
}
P.transport["quest:645"] = {
  hash = "fc8b0f",
  fullHash = "fc8b0f",
  text = "Trol'kalar. Following the Sigil of Trollbane, Zengu finds that the four sigils have formed a single one that can break the wardings on Trollbane's tomb. He sends you to Stromgarde to retrieve Trol'kalar from the tomb. Zengu finds that the four sigils have come together and formed one, the Sigil of Ignaeus. He has no doubt it can break the wardings placed on Trollbane's tomb. Trollbane lies entombed in Stromgarde, in the Sanctum that lies behind the chapel, and Zengu sends you there to retrieve Trol'kalar. A fenced path beside the chapel entrance, on its right, descends to the crypt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_645-a7d8d5b63acc114763e1/1-0000.mp3", duration = 33.2016327, start = 0},
  },
}
P.transport["quest:646"] = {
  hash = "886eb7",
  fullHash = "886eb7",
  text = "Trol'kalar. The long Trol'kalar chain reaches its last step. The light slowly fades, and Trol'kalar, held in a stone sheath, is released. Carry it to Zengu in Hammerfall. At Trollbane's Tomb the light slowly fades, and Trol'kalar, kept in a stone sheath, is released. You take the sheathed sword to Zengu in Hammerfall, in the Arathi Highlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_646-42c47448e7da56858ba9/1-0000.mp3", duration = 20.7412245, start = 0},
  },
}
P.transport["quest:653"] = {
  hash = "f6504f",
  fullHash = "f6504f",
  text = "Myzrael's Allies. Myzrael cries out that she is free, and that she will gather her strength in hiding from her captors. She calls you a noble ally and sends you to Gerrig Bonegrip in a shop of Ironforge's Forlorn Cavern, who knows how she can be summoned. Myzrael is free, and means to gather strength hidden from her captors, since if they met her now they would surely overpower her and lock her away again. In time she means to face the giants, and she swears they will rue having held her. She calls you a noble ally and says she will need your help again, to summon her to the surface when she is ready. Myzrael tells you to speak with Gerrig Bonegrip, whose shop is in Ironforge, in the Forlorn Cavern. He knows how she can be summoned.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_653-f9ed09feb22dc1a4d3ba/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["quest:656"] = {
  hash = "baae97",
  fullHash = "baae97",
  text = "Summoning the Princess. Theldurin the Lost says Myzrael must be beaten while she is still growing, before her strength is enough to challenge those who hold her captive. At the Shards of Myzrael you call her forth, defeat her, and bind her Eldritch Shackles to the Shards. Theldurin wants Myzrael stopped before her power swells enough to set her against her captors. Some claim she can be controlled; Theldurin asks why, then, the giants bothered to chain her at all. You take the Scroll of Myzrael to the Shards, the place where you first talked with her, and call her up. After you defeat her, her Eldritch Shackles are yours to bind to the Shards, and she is trapped once more.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_656-fcc815e55c742148a047/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["quest:6568"] = {
  hash = "28dc1a",
  fullHash = "28dc1a",
  text = "The Testament of Rexxar. Rexxar says that slipping past the Black Flight's defenses calls for an illusion. He knows a master illusionist, Myranda the Hag, who lives in the Western Plaguelands, and sends you to her with a message. Rexxar asks what you know of illusions, since an illusion is how you will get around the Black Flight's defenses. He names someone who may assist you in such deception: Myranda the Hag, a master illusionist driven out by the Lordaeron alliance, living in the Western Plaguelands. Rexxar says she has lent his kind a hand before, whenever she found a cause worthy. You carry his message to her. Myranda remarks that a member of the Horde is a rare sight in these parts of Lordaeron, and she asks what you have brought her.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6568-e066c3e32c3baadb2629/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["quest:662"] = {
  hash = "6b5f7a",
  fullHash = "6b5f7a",
  text = "Deep Sea Salvage. Following Land Ho!, First Mate Nilzlix asks you to bring back the charts and logs of two sunken ships before anyone leaves the cove. O'Breen led three ships into the cove, certain the treasure lay here. The Harbinger docked safely. Then, as the Maiden's Folly with the Spirit of Silverpine came in, the tides began to lower, and both ships ran aground on a temple-like structure in the reef and sank fast. Nilzlix wants the logs and the charts of both wrecked ships recovered, since that information must not be left behind for prying eyes. If it reached enemy hands, he says, Fleet Master Seahorn would force the crew down the plank.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_662-8fbf4ad5601a6a8d8b82/1-0000.mp3", duration = 37.6946939, start = 0},
  },
}
P.transport["quest:664"] = {
  hash = "f7173c",
  fullHash = "f7173c",
  text = "Drowned Sorrows. Captain Steelgut sits mourning at Faldir's Cove after losing the beloved Maiden's Folly. Steelgut asks you to go after the Daggerspine naga who slaughtered the survivors of the wreck. Captain Steelgut sits by the fire at Faldir's Cove, wishing for a watery grave instead. The crew fought hard to save the beautiful Maiden's Folly, but the sea sank it, with water rushing in all at once. O'Breen reached shore safely, yet naga killed the survivors. Steelgut wants Daggerspine raiders and sorceresses dead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_664-d87e8d0da09f9d86e195/1-0000.mp3", duration = 31.2163265, start = 0},
  },
}
P.transport["quest:665"] = {
  hash = "5ad589",
  fullHash = "5ad589",
  text = "Sunken Treasure. Now that they are full-fledged Blackwater Raiders, Professor Phizzlethorpe and Doctor Draxlegauge are to help Mr. O'Breen find the lost elven treasure. To search the dark sea for the gems, the professor needs your protection while he charges a pair of goggles at an enchanted stone in a cave. The gems are next to impossible to find in the dark sea without help, so Doctor Draxlegauge has built goggles for the search. They need charging with power from the enchanted stone, in a cave a short way uphill. The cave is cursed, though: those who draw near are ambushed. Professor Phizzlethorpe asks you to defend him while he draws the stone's energy into the goggles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_665-2bb236b4083b69a0631b/1-0000.mp3", duration = 38.2693878, start = 0},
  },
}
P.transport["quest:666"] = {
  hash = "15462b",
  fullHash = "15462b",
  text = "Sunken Treasure. In Faldir's Cove, Doctor Draxlegauge lends you his goggles to find ten elven gems for Captain O'Breen. He expects them back when you finish. The elven gems have lain on the sea floor so long that thick stone has hardened around them. The Goggles of Gem Hunting hold the power to find them through those stony shells. Proud of the gnomish ingenuity behind the goggles, Doctor Draxlegauge lends them to you. The gems are for Captain O'Breen. Doctor Draxlegauge says scientific work keeps him on safe, dry land, though he could swim down himself. He expects you to return the goggles afterward. Captain O'Breen, he says, will have plenty of use for them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_666-3a3337ad35417c2c7a06/1-0000.mp3", duration = 39.4187755, start = 0},
  },
}
P.transport["quest:667"] = {
  hash = "9e7784",
  fullHash = "9e7784",
  text = "Death From Below. In the Arathi Highlands, Shakes O'Breen expects the Daggerspine naga to attack from the sea, and the crew cannot sail home to Booty Bay without O'Breen's knowledge of the waters. You stay aboard beside O'Breen, man the cannon and drive the naga back. After Sunken Treasure, Shakes O'Breen sees the Daggerspines gathering to attack. Naga have a name for ruthlessness and will keep coming until O'Breen is dead. O'Breen does not value their own life above those of the crew, but asks you to defend them, since the crew cannot reach Booty Bay without that knowledge of the seas. You wait aboard with O'Breen for the naga to come from the water.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_667-0a0977bd41da43c4c6de/1-0000.mp3", duration = 37.4595918, start = 0},
  },
}
P.transport["quest:668"] = {
  hash = "abc83a",
  fullHash = "abc83a",
  text = "Sunken Treasure. Doctor Draxlegauge hands you the elven gems and sends you to carry them to Captain O'Breen. After a few weeks among pirates, he and the professor know that holding on to their treasure is unhealthy. Doctor Draxlegauge does not want Captain O'Breen kept waiting, since the captain will want to see the elven gems for himself. After weeks among these pirates, the doctor and the professor have learned that being caught holding on to pirate treasure is bad for their health. He hands you the gems to carry to O'Breen, who waits at the bridge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_668-a951b5814a8e69699c41/1-0000.mp3", duration = 28.8130612, start = 0},
  },
}
P.transport["quest:669"] = {
  hash = "3abf9b",
  fullHash = "3abf9b",
  text = "Sunken Treasure. After the previous step in the Sunken Treasure chain, Shakes O'Breen is stuck where he is and needs word taken to Fleet Master Seahorn at Booty Bay. He asks you to carry a sample gem as proof of the find. Shakes O'Breen wants Fleet Master Seahorn to hear of the find right away, yet he cannot easily get away. The tide is too low, and the creatures they disturbed are watching every move. He asks you to help the Blackwater Raiders by telling Seahorn in Booty Bay that the treasure is found and more is being brought up. A sample elven gem goes with you as proof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_669-c0e329edfb836fe865e4/1-0000.mp3", duration = 32.5746939, start = 0},
  },
}
P.transport["quest:670"] = {
  hash = "bd8cc6",
  fullHash = "bd8cc6",
  text = "Sunken Treasure. Fleet Master Seahorn, whose ships cannot sail from Booty Bay until they restock, asks you to carry a secret letter to Shakes O'Breen, busy off the Arathi coast. Fleet Master Seahorn sizes you up as the adventurous sort. His ships cannot leave Booty Bay until they have restocked, and he says heavy things are brewing both here and abroad. He needs top secret correspondence carried to Shakes O'Breen off the Arathi coast, and he asks whether he can trust you to deliver the message safely and in confidence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_670-b43896d4429dbe2ad4ab/1-0000.mp3", duration = 28.2644898, start = 0},
  },
}
P.transport["quest:673"] = {
  hash = "f86326",
  fullHash = "f86326",
  text = "Foul Magics. Tor'gan in Hammerfall is sure that a powerful warlock lives within the walls of Stromgarde and uses an arcane relic to summon demons in large numbers. Following the first part of Foul Magics, he sends you to kill the warlock and bring back the relic. Tor'gan is certain that a warlock lives within Stromgarde's walls. Now and then the warlock uses an arcane relic to call up terrible demons in great numbers. The burning in Tor'gan's blood grows by the day. He wants the warlock found and killed, and whatever magical object is on the body brought to him, so that he can destroy it and keep its power from tainting the land. The warlock is Marez Cowl, and the object is a Befouled Bloodstone Orb.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_673-694daf7a1ad503f0948b/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["quest:679"] = {
  hash = "193e8a",
  fullHash = "193e8a",
  text = "Call to Arms. Following the previous Call to Arms, Drum Fel at Hammerfall declares that it is time to strike the head from the beast. He sends you after the Boulderfist lords and shaman who lair in the ruins of Stromgarde. Drum Fel says you have proven able enough to help deliver one last great blow. Those leading the attacks have made their lair in the ruins of Stromgarde, which he calls a symbol of human frailty. Hunt down the Boulderfist lords and the shaman who serve them, for they would try to drive the Horde out of these lands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_679-a99fb1ef00a3bfdd41f3/1-0000.mp3", duration = 29.204898, start = 0},
  },
}
P.transport["quest:680"] = {
  hash = "d542d7",
  fullHash = "d542d7",
  text = "The Real Threat. Following Call to Arms, Korin Fel tells you that her husband is unaware of why Hammerfall is under attack, and asks you to slay the ogre Or'Kalar and bring her his head. Korin Fel says you serve her husband well, yet he has no idea why Hammerfall is being attacked. The cause is Or'Kalar, Mug'thol's pawn in Stromgarde, who hates her husband for defeating him years ago and wants him dead. Her auguries tell her the ogre has set a trap for him. Korin has hidden the signs of the ogre's presence from her husband, who she believes would rush off foolishly if he knew where Or'Kalar is. She asks for your help instead. You will find Or'Kalar near the Tower of Arathor, and she expects his death to end the attacks on Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_680-199bcbe4e693403c0821/1-0000.mp3", duration = 41.7697959, start = 0},
  },
}
P.transport["quest:687"] = {
  hash = "03d787",
  fullHash = "03d787",
  text = "Theldurin the Lost. A member of the Twilight's Hammer asks you to find Theldurin the Lost, who was once of their order, lost his mind, and fled with the scroll of Myzrael. Rumor places him in the Badlands. Theldurin once belonged to the Twilight's Hammer, until his mind slipped and he turned his back on the order's teachings. As he fled, he took the scroll of Myzrael with him. Those he left behind could not catch him. The order has heard that Theldurin hides in the Badlands, raving and mad. The scroll is needed for the Lady's return, and to get it you must first find the man who took it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_687-af071eeaffc23d7f80cd/1-0000.mp3", duration = 33.2016327, start = 0},
  },
}
P.transport["quest:688"] = {
  hash = "49b880",
  fullHash = "49b880",
  text = "Myzrael's Allies. Myzrael speaks through the keystone, declaring herself free but in hiding from her captors, and tells you to speak with Zaruk in Hammerfall, who knows how she can be summoned. Myzrael cries out that she is free. For now she must gather her strength out of sight of her captors, because if they faced her today they would overpower and imprison her again. In time, she vows, she will confront the giants who held her, and they will regret keeping her. Myzrael calls you a noble ally and says she will want your aid again in time. When she is ready, she will have you summon her to the surface. For now she sends you to Zaruk in Hammerfall, who knows how it can be done.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_688-321117d4dfb22a86ae68/1-0000.mp3", duration = 38.0865306, start = 0},
  },
}
P.transport["quest:7810"] = {
  hash = "32019a",
  fullHash = "32019a",
  text = "Arena Master. Is there more to mastering the arena than this? Short John Mithril, the Pirate behind the Gurubashi event, may have the answer, and you will find him in the Stranglethorn Arena. Whatever you have gained at Gurubashi, it seems that mastering the arena asks for more. Short John Mithril, the Pirate who organizes the contests there, may know what. Look for him inside the Stranglethorn Arena.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7810-1dd6fde878ec03d2b95d/1-0000.mp3", duration = 24.6595918, start = 0},
  },
}
P.transport["quest:8552"] = {
  hash = "260dc9",
  fullHash = "260dc9",
  text = "The Monogrammed Sash. A fine sash bearing embroidered initials hints at a rightful owner somewhere in Stranglethorn Vale. Finding the seafarer who lost it leads on to The Captain's Cutlass. This fine sash bears the letters 'HS' embroidered along its hem. Whoever lost it can only be traced by those two letters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8552-b72da4c6cbb0cd6890e0/1-0000.mp3", duration = 16.6661224, start = 0},
  },
}
P.transport["quest:8553"] = {
  hash = "d7a6b0",
  fullHash = "d7a6b0",
  text = "The Captain's Cutlass. Captain Hecklebury Smotts bought a second vessel named Smotts' Revenge to hunt down the sea giants who took his first ship, only to suffer another defeat. The giants smashed the vessel and killed the crew, and one of them, Negolash, stole the captain's cutlass. Smotts directs you to consult his former ship cook, Sprogger, to track down the behemoth. Following the loss of his initial ship, Captain Hecklebury Smotts procured a second craft called Smotts' Revenge, gathering a fresh crew and provisions to take vengeance on the sea giants. The venture ended in disaster when the giants shattered the ship and slew the crew, leaving Smotts adrift once more in a lifeboat. During the onslaught, the giant Negolash took the captain's cutlass. Determined to retrieve his stolen blade, Smotts relies on his cook. Sprogger, who served aboard Smotts' Revenge, lived through the attack and can help find Negolash.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8553-7f25128403f3adb1e57a/1-0000.mp3", duration = 51.6702041, start = 0},
  },
}
P.transport["quest:8742"] = {
  hash = "282dae",
  fullHash = "282dae",
  text = "The Might of Kalimdor. In Tanaris, Anachronos greets you in The Might of Kalimdor as the champion fate has awaited for a thousand years. He sees you leading your people into a new age. The Blue, Green and Red Scepter Shard forks are complete, bringing the Scepter of the Shifting Sands to its end. Anachronos speaks of a fate a thousand years in the making. The Old God trembles at your coming and fears your faith. Anachronos urges you to break C'Thun's prophecy, and you bring Kalimdor's strength with you. When you are ready, tell Anachronos, and he will place the Scepter of the Shifting Sands in your hands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8742-bb0c8e4981f5cc1c8236/1-0000.mp3", duration = 34.9779592, start = 0},
  },
}
